"""Public, user-authorized fixtures. Reference transcriptions are manual, not generated by an OCR engine."""
from pathlib import Path
import json
from PIL import Image

ROOT = Path(__file__).resolve().parents[1] / "artifacts/multimodal-evaluation"
INPUTS = ROOT / "inputs"
REFERENCES = [
    ("m1-long", "manga-001", (.375,.10,.54,.20), "WHAT TOOK YOU SO LONG?"),
    ("m1-nazuna", "manga-001", (.70,.12,.845,.215), "HEY, NAZUNA!"),
    ("m1-late", "manga-001", (.37,.38,.51,.48), "YOU'RE LATE, NAZUNA."),
    ("m1-drinking", "manga-001", (.74,.37,.91,.51), "WE'VE ALREADY STARTED DRINKING."),
    ("m1-beer", "manga-001", (.69,.65,.895,.79), "NAZUNA! HEY, CAN WE GET ANOTHER BEER OVER HERE?"),
    ("m1-again", "manga-001", (.74,.80,.85,.90), "LATE AGAIN..."),
    ("m2-anyway", "manga-002", (.13,.10,.34,.235), "SO, ANYWAY, KABURA, THAT'S WHEN I WAS LIKE..."),
    ("m2-here", "manga-002", (.60,.095,.745,.205), "HERE YOU GO!"),
    ("m2-dorks", "manga-002", (.735,.085,.985,.26), "WHY THE HELL DO I HANG OUT WITH THESE DORKS EVERY NIGHT?"),
    ("m2-haru", "manga-002", (.13,.37,.325,.54), "...HARU! YOU'RE MAKING THIS ALL ABOUT YOU! AGAIN!"),
    ("m2-listening", "manga-002", (.265,.57,.44,.73), "ARE YOU LISTENING, KABURA? HEYYY!"),
    ("m2-amazing", "manga-002", (.105,.635,.25,.77), "OH... YEAH. THAT'S AMAZING, HARUKA."),
    ("m5-hear", "manga-005", (.20,.09,.325,.22), "YOU HEAR ME, KABURA?"),
    ("m5-gripes", "manga-005", (.36,.095,.505,.24), "THEY REHASH THE SAME GRIPES OVER AND OVER AND OVER AGAIN."),
    ("m5-loses", "manga-005", (.77,.08,.91,.21), "I KNOW, I KNOW. THE ONE WHO FALLS THE HARDEST ALWAYS LOSES."),
    ("m5-back", "manga-005", (.52,.185,.665,.315), "BUT I CAN'T BELIEVE SHE UP AND DIED ON ME BEHIND MY BACK!"),
    ("m5-haru", "manga-005", (.235,.35,.385,.46), "IT ALL BOILS DOWN TO HARU'S NARCISSISTIC TENDENCIES."),
    ("m5-right", "manga-005", (.53,.36,.65,.485), "YEAH! YOU'RE SO RIGHT!"),
    ("m5-reactions", "manga-005", (.41,.40,.523,.515), "NOT EVEN THEIR REACTIONS CHANGE."),
    ("m5-conclusion", "manga-005", (.475,.625,.63,.745), "...AND THEY ALWAYS COME TO THE SAME CONCLUSION."),
    ("m5-cute", "manga-005", (.64,.62,.88,.77), "THAT'S WHAT WAS SO CUTE ABOUT HER."),
    ("m5-crap", "manga-005", (.085,.82,.24,.91), "I COULDN'T GIVE LESS OF A CRAP."),
    ("scroll-beer", "manga-scroll-01", (.615,.17,.74,.385), "NAZUNA! HEY, CAN WE GET ANOTHER BEER OVER HERE?"),
    ("scroll-again", "manga-scroll-01", (.635,.42,.72,.585), "LATE AGAIN..."),
]

manifest = []
references = []
for name in ("manga-001", "manga-002", "manga-003", "manga-005"):
    image = Image.open(INPUTS / (name + ".png")).convert("RGB")
    manifest.append({"id":name,"path":str(INPUTS / (name + ".png"))})
    resized = image.resize((730,1095), Image.Resampling.LANCZOS)
    resized.save(INPUTS / (name + "-730.png"))
    manifest.append({"id":name+"-730","path":str(INPUTS / (name + "-730.png"))})
for name in ("manga-screen","manga-scroll-01","manga-scroll-02"):
    if (INPUTS / (name+".png")).exists():
        manifest.append({"id":name,"path":str(INPUTS / (name+".png"))})
for label, name, box, text in REFERENCES:
    image = Image.open(INPUTS / (name + ".png")).convert("RGB")
    coordinates = [round(box[0]*image.width), round(box[1]*image.height), round(box[2]*image.width), round(box[3]*image.height)]
    path = INPUTS / (label + ".png")
    image.crop(coordinates).save(path)
    manifest.append({"id":label,"path":str(path)})
    references.append({"id":label,"page":name,"box":box,"text":text})

# Known frame transcriptions; blank samples detect false positives in the subtitle ROI.
for label, region, text in [
    ("video-01", (35,68,705,91), "The wind shakes laden frost; the umbrella's ribs groan"),
    ("video-02", (35,68,705,91), ""),
    ("video-03", (35,68,705,91), ""),
    ("video-04", (35,68,705,91), ""),
    ("video-06", (100,416,680,438), "I knew you were born of feeling. Your capacity for joy and sorrow far exceeds my own."),
    ("video-07", (100,416,680,438), "Go. Walk forward, one step at a time. Walk farther and better than I ever could."),
    ("video-08", (100,416,680,438), ""),
]:
    path = INPUTS / (label+".png")
    if not path.exists():
        continue
    image = Image.open(path).convert("RGB")
    roi_path = INPUTS / (label+"-roi.png")
    image.crop(region).save(roi_path)
    manifest.append({"id":label+"-roi","path":str(roi_path)})
    references.append({"id":label+"-roi","text":text,"frame":label})

(ROOT / "manifest.json").write_text(json.dumps(manifest,indent=2),encoding="utf8")
(ROOT / "references.json").write_text(json.dumps(references,indent=2),encoding="utf8")
print(f"Prepared {len(manifest)} inputs and {len(references)} manually transcribed regions")
